@Composable
fun StartRegistrationPage(
    modifier: Modifier = Modifier,
    component: StartRegistrationPageComponent
) {

    val state by component.state.collectAsState()

    val pages by component.pages.subscribeAsState()
    val activeStage = pages.active.instance.value
    val distanceTitle = (activeStage as? StartRegistrationStagePage.Registration)
        ?.title?.takeIf { it.isNotBlank() }

    val snackBarHostState by remember {
        mutableStateOf(SnackbarHostState())
    }
    var snackBarColor by remember {
        mutableStateOf(SportSouceColor.SportSouceLighBlue)
    }

    Scaffold(
        modifier = modifier,
        topBar = {
            TopBarBase(
                title = distanceTitle ?: state.registrationInfo.startTitle,
                titleMaxLines = if (distanceTitle != null) 1 else 2,
            ) {
                component.obtainEvent(StartRegistrationPageStore.Intent.OnClickGoBack)
            }
        },
        snackbarHost = {
            SnackbarHost(
                hostState = snackBarHostState
            ) {
                Snackbar(
                    contentColor = Color.White,
                    containerColor = snackBarColor,
                    dismissActionContentColor = Color.White,
                    snackbarData = it
                )
            }
        }
    ) { paddingValues ->

        AdaptivePane(modifier = Modifier.padding(paddingValues).consumeWindowInsets(paddingValues).imePadding()) {
            when {
                state.pagesState.isLoading -> LoadingFullScreen(Modifier.fillMaxSize())
                state.pagesState.error != null -> state.pagesState.error?.SauceErrorScreen()
                else -> Children(
                    stack = pages,
                    animation = stackAnimation(animator = slide()),
                ) { child ->
                    val page = child.instance
                    RegistrationStageViewport {
                        when (page) {
                            is StartPayComponent -> StartPay(modifier = Modifier, component = page)
                            is StartDistanceComponent -> StartStage(modifier = Modifier, component = page)
                        }
                        StartStagesIndicatorContent(
                            modifier = Modifier.padding(16.dp),
                            currentIndex = page.value.id,
                            startRegistrationStage = state.stages,
                        )
                    }
                }
            }
        }
    }

    EventEffect(
        event = state.eventWithContent,
        onConsumed = {
            component.obtainEvent(StartRegistrationPageStore.Intent.OnConsumedEvent)
        },
    ) {
        snackBarColor =
            if (it.success) SportSouceColor.SportSouceLighBlue else SportSouceColor.SportSouceLightRed
        snackBarHostState.showLongMessageWithDismiss(message = it.message)
    }
}
