import com.markettwits.sportsouce.news.news_event.component.NewsEventInput
import com.markettwits.sportsouce.news.news_event.store.NewsEventStoreFactory
import com.markettwits.sportsouce.news.news_list.component.NewsComponentBase
import com.markettwits.sportsouce.news.root.RootNewsComponentBase
import com.markettwits.sportsouce.review.review.di.reviewModule
import com.markettwits.sportsouce.review.review.presentation.component.ReviewComponentBase
import com.markettwits.sportsouce.review.root.di.reviewRootModule
import com.markettwits.sportsouce.settings.root.RootSettingsComponentBase
import com.markettwits.sportsouce.shop.catalog.di.shopCatalogModule
import com.markettwits.sportsouce.shop.root.RootShopCatalogComponentBase
import com.markettwits.sportsouce.start.presentation.start.component.StartScreenInput
import com.markettwits.sportsouce.start.root.RootStartScreenComponentBase
import com.markettwits.sportsouce.start.search.root.RootStartsSearchComponentBase
import com.markettwits.sportsouce.starts.popular.root.RootStartsPopularComponentBase
import com.markettwits.sportsouce.starts.random.root.presentation.RootStartRandomComponentBase


class RootReviewComponentBase(
    context: ComponentContext,
    private val updateStoreFactory: SelfUpdateStoreFactory,
    override val notifications: NotificationApi,
) : RootReviewComponent,
    ComponentContext by context {

    private val notificationScope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)
    init {
        lifecycle.doOnResume { notificationScope.launch { notifications.refreshUnreadCount() } }
        lifecycle.doOnDestroy { notificationScope.cancel() }
    }

    private val navigation = StackNavigation<RootReviewComponent.Config>()

    private val koinContext = instanceKeeper.getOrCreate {
        ComponentKoinContext()
    }

    private val scope = koinContext.getOrCreateKoinScope(
        listOf(
            reviewRootModule,
            newsModule,
            reviewModule,
            shopCatalogModule,
            clubDashboardModule,
            workoutRegistrationModule,
            startAlbumModule
        )
    )

    override val childStack: Value<ChildStack<*, RootReviewComponent.Child>> = childStack(
        source = navigation,
        serializer = RootReviewComponent.Config.serializer(),
        initialStack = { getInitialStack() },
        handleBackButton = true,
        childFactory = ::child,
    )

    override fun openNotifications() { navigation.pushNew(RootReviewComponent.Config.Inbox) }

    override fun popToRoot() {
        navigation.popTo(0)
    }

    private fun getInitialStack(): List<RootReviewComponent.Config> {
        return listOf(RootReviewComponent.Config.Review)
    }

    private fun createNewsEventStoreFactory() = NewsEventStoreFactory(
        storeFactory = DefaultStoreFactory(),
        newsRepository = scope.get()
    )

    override fun handleDeeplink(deeplink: Deeplink.News) {
        when (deeplink) {
            is Deeplink.News.NewsDetail -> {
                // Navigate to news detail while preserving navigation stack
                navigation.pushNew(RootReviewComponent.Config.NewsEventById(deeplink.newsId))
            }
        }
    }

    override fun handleDeeplink(deeplink: Deeplink.Clubs) {
        when (deeplink) {
            is Deeplink.Clubs.ClubsList -> {
                // Navigate to clubs while preserving navigation stack
                navigation.pushNew(RootReviewComponent.Config.Club)
            }
        }
    }

    override fun handleDeeplink(deeplink: Deeplink.Shop) {
        when (deeplink) {
            is Deeplink.Shop.ShopRoot -> {
                // Navigate to shop while preserving navigation stack
                navigation.pushNew(RootReviewComponent.Config.Shop())
            }

            is Deeplink.Shop.ShopProduct -> {
                navigation.pushNew(
                    RootReviewComponent.Config.Shop(
                        categoryId = deeplink.categoryId,
                        productId = deeplink.productId
                    )
                )
            }
        }
    }

    override fun openUpdate(version: NewAppVersion) {
        navigation.pushNew(RootReviewComponent.Config.Notification(version))
    }

    private fun child(
        config: RootReviewComponent.Config,
        componentContext: ComponentContext,
    ): RootReviewComponent.Child =
        when (config) {
            is RootReviewComponent.Config.Review -> RootReviewComponent.Child.Review(
                component = ReviewComponentBase(
                    context = componentContext,
                    storeFactory = scope.get(),
                    onStartClick = {
                        navigation.pushNew(RootReviewComponent.Config.Start(it))
                    },
                    onClickMenu = {
                        navigation.pushNew(handleMenu(it))
                    },
                    onClickSearch = {
                        navigation.pushNew(RootReviewComponent.Config.Search)
                    },
                    onClickNews = {
                        navigation.pushNew(RootReviewComponent.Config.NewsEvent(it))
                    },
                    onClickPhotoAlbum = { id -> navigation.pushNew(RootReviewComponent.Config.PhotoAlbum(id)) },
                    onClickSettings = {
                        navigation.pushNew(RootReviewComponent.Config.Settings)
                    },
                    onClickProduct = {
                        handleDeeplink(
                            Deeplink.Shop.ShopProduct(
                                productId = it.id,
                                categoryId = it.categories.firstOrNull()?.id
                            )
                        )
                    }

                ),
                newsComponent = NewsComponentBase(
                    context = componentContext,
                    storeFactory = scope.get(),
                    onItemClick = {
                        navigation.pushNew(RootReviewComponent.Config.NewsEvent(it))
                    }
                )
            )

            is RootReviewComponent.Config.StartById -> RootReviewComponent.Child.Start(
                RootStartScreenComponentBase(componentContext, StartScreenInput.Id(config.id), pop = navigation::pop)
            )

            is RootReviewComponent.Config.Start -> RootReviewComponent.Child.Start(
                RootStartScreenComponentBase(
                    context = componentContext,
                    input = StartScreenInput.Item(config.startItem),
                    pop = navigation::pop
                )
            )

            is RootReviewComponent.Config.Random -> RootReviewComponent.Child.Random(
                RootStartRandomComponentBase(
                    context = componentContext,
                    dependencies = scope.get(),
                    pop = navigation::pop
                )
            )

            is RootReviewComponent.Config.Popular -> RootReviewComponent.Child.Popular(
                RootStartsPopularComponentBase(
                    context = componentContext,
                    pop = navigation::pop,
                )
            )

            is RootReviewComponent.Config.News -> RootReviewComponent.Child.News(
                RootNewsComponentBase(
                    context = componentContext,
                    pop = navigation::pop
                )
            )

            is RootReviewComponent.Config.NewsEvent -> RootReviewComponent.Child.NewsEvent(
                NewsEventComponentBase(
                    context = componentContext,
                    input = NewsEventInput.Item(config.news),
                    storeFactory = createNewsEventStoreFactory(),
                    onBack = navigation::pop
                )
            )

            is RootReviewComponent.Config.NewsEventById -> RootReviewComponent.Child.NewsEvent(
                NewsEventComponentBase(
                    context = componentContext,
                    input = NewsEventInput.Id(config.newsId),
                    storeFactory = createNewsEventStoreFactory(),
                    onBack = navigation::pop
                )
            )

            is RootReviewComponent.Config.Albums -> RootReviewComponent.Child.Albums(
                RootStartsAlbumsComponentBase(componentContext, navigation::pop)
            )

            is RootReviewComponent.Config.PhotoAlbum -> RootReviewComponent.Child.PhotoAlbum(
                StartAlbumComponentBase(componentContext = componentContext, storeFactory = scope.get(),
                    albumId = config.albumId, pop = navigation::pop)
            )

            is RootReviewComponent.Config.Search -> RootReviewComponent.Child.Search(
                RootStartsSearchComponentBase(
                    context = componentContext,
                    pop = navigation::pop
                )
            )

            is RootReviewComponent.Config.Notification -> RootReviewComponent.Child.Notification(
                SelfUpdateComponentBase(
                    componentContext = componentContext,
                    newAppVersion = config.newAppVersion,
                    storeFactory = updateStoreFactory,
                    goBack = navigation::pop
                )
            )

            is RootReviewComponent.Config.Inbox -> RootReviewComponent.Child.Inbox(
                notifications.createComponent(componentContext, onBack = { navigation.pop() }, onOpenStart = { id ->
                    navigation.pushNew(RootReviewComponent.Config.StartById(id))
                })
            )

            is RootReviewComponent.Config.Settings -> RootReviewComponent.Child.Settings(
                RootSettingsComponentBase(
                    componentContext = componentContext,
                    pop = navigation::pop,
                    updateStoreFactory = updateStoreFactory,
                )
            )

            is RootReviewComponent.Config.Club -> RootReviewComponent.Child.Club(
                RootClubComponentBase(
                    componentContext = componentContext,
                    pop = navigation::pop
                )
            )

            is RootReviewComponent.Config.Shop -> RootReviewComponent.Child.Shop(
                RootShopCatalogComponentBase(
                    componentContext = componentContext,
                    pop = navigation::pop,
                    initialProductId = config.productId,
                    initialCategoryId = config.categoryId
                )
            )
        }

    private fun handleMenu(itemId: Int): RootReviewComponent.Config {
        return when (itemId) {
            0 -> RootReviewComponent.Config.Popular
            1 -> RootReviewComponent.Config.News
            2 -> RootReviewComponent.Config.Club
            3 -> RootReviewComponent.Config.Albums
            4 -> RootReviewComponent.Config.Shop()
            577 -> RootReviewComponent.Config.Shop(categoryId = 577)
            582 -> RootReviewComponent.Config.Shop(categoryId = 582)
            else -> RootReviewComponent.Config.Search
        }
    }
}
